import{_ as d,o,c,a2 as s}from"./chunks/framework.SkWZtmk2.js";const u=JSON.parse('{"title":"文档站维护","description":"","frontmatter":{},"headers":[],"relativePath":"internal/maintenance.md","filePath":"internal/maintenance.md"}'),a={name:"internal/maintenance.md"};function t(i,e,n,r,p,l){return o(),c("div",null,[...e[0]||(e[0]=[s(`<h1 id="文档站维护" tabindex="-1">文档站维护 <a class="header-anchor" href="#文档站维护" aria-label="Permalink to &quot;文档站维护&quot;">​</a></h1><p>本页面向仓库维护者。业务接入从<a href="./../guide/getting-started.html">快速开始</a>开始。</p><h2 id="启动与构建" tabindex="-1">启动与构建 <a class="header-anchor" href="#启动与构建" aria-label="Permalink to &quot;启动与构建&quot;">​</a></h2><p>在仓库根目录执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span></code></pre></div><p><code>pnpm typecheck</code> 在构建库后对 <code>docs/designer</code>、<code>docs/examples</code>、<code>docs/playground</code> 中的 TS / Vue 示例及 <code>.vitepress/components</code> 下的组件与测试进行类型检查。示例从 <code>@printstack/print-studio</code>、<code>@printstack/print-studio/vue</code>、<code>@printstack/print-studio/designer</code>、<code>@printstack/print-studio/core</code>、<code>@printstack/print-studio/printer</code> 公共入口导入，对照当前构建产物验证。</p><p><code>docs:build</code> 先执行上述检查，再构建示例容器和 VitePress 站点。产物为 <code>dist/docs/</code>；部署子路径时设置 <code>DOCS_BASE</code> 后重新构建。<code>pnpm build</code> 包含项目、库与文档站构建。</p><h2 id="设计器主题" tabindex="-1">设计器主题 <a class="header-anchor" href="#设计器主题" aria-label="Permalink to &quot;设计器主题&quot;">​</a></h2><p>设计器样式入口 <code>src/styles/design-system.css</code> 依次引入 TDesign、<code>main.css</code>、<code>tdesign-theme.css</code> 和 <code>designer-density.css</code>，供 iframe 和 standalone 模式使用。客户端通过公开入口 <code>@printstack/print-studio/theme.css</code> 复用配色和 TDesign 颜色映射，密度由客户端样式定义。</p><p>深色主题使用 <code>data-theme=&quot;dark&quot;</code>。<code>theme-mode</code> 仍用于 TDesign 的深浅色模式；浅色模式标记为 <code>data-theme=&quot;daylight-blue&quot;</code>，使用浅灰蓝背景、白色表面和蓝色主操作色。背景、文字、边框、语义色及画布辅助标记等颜色在 <code>src/styles/theme-colors.css</code> 定义，预览背景色在 <code>src/styles/preview-colors.css</code> 定义；<code>src/styles/tdesign-theme.css</code> 将设计器色板映射为 TDesign 色阶和交互状态。完整打印预览将所需色板同步到预览 iframe；普通 iframe 预览复用预览背景色板。两者均随所在文档的主题切换更新；纸张与打印内容使用文档自身的颜色。<code>t-alert</code> 使用低饱和底色、语义色边线和常规正文色。深色的输入框占位文字使用 <code>#8290A6</code>；实底主操作和危险操作使用独立底色配白字，按钮在默认、悬停、键盘聚焦和按下时均保持白字；实底警告继续使用亮琥珀底配深色文字。浅色 TDesign 圆角使用 4、6、8、12px。深浅主题复用键盘焦点规则，输入控件的焦点边框和光环随校验状态变化。</p><p>深色主题下，面板、菜单及元素设置中的主要选中态使用 <code>#155BD7</code> 配白字；普通表面与悬停状态使用独立的背景色。文本变量标签在画布展示和编辑时均使用浅蓝底、深色文字；无效变量使用深红文字。</p><p>打印预览从计算样式读取色板变量，因此 <code>theme-colors.css</code> 使用 <code>@theme static</code> 保留未生成 Tailwind 工具类的变量。</p><h2 id="示例容器与浏览器检查" tabindex="-1">示例容器与浏览器检查 <a class="header-anchor" href="#示例容器与浏览器检查" aria-label="Permalink to &quot;示例容器与浏览器检查&quot;">​</a></h2><p><code>docs:playground</code> 使用构建后的 <code>packages/print-studio/dist</code> 公共入口，将独立 Vue 应用生成到 <code>docs/public/playground/</code>，由文档站复制到输出目录。生成文件已忽略，不提交。<code>docs:dev</code> 和 <code>docs:build</code> 都先准备容器；修改示例源码后需重新执行 <code>pnpm docs:playground</code>。</p><p><code>docs:designer</code> 同样基于 <code>packages/print-studio/dist</code> 公共入口，把 <code>docs/designer/</code> 构建为全屏独立设计器页面 <code>docs/public/designer/</code>（挂载 <code>@printstack/print-studio/designer</code> 的 <code>attachDesigner</code>，文档持久化到 localStorage）。没有已保存文档时打开内置欢迎模板；已有保存内容时优先恢复。导航栏「设计器」入口指向 <code>/designer/index.html</code>；修改 <code>docs/designer/</code> 源码后需重新执行 <code>pnpm docs:designer</code>。</p><p>文档通过 <code>DemoFrame</code> / <code>PlaygroundEmbed</code> 组件引用容器，使用 <code>withBase</code> 适配站点子路径并附带 <code>embed=1</code> 隐藏容器自带头部；容器自己的资源使用相对路径。仅切换页面不把设计器样式引入文档主题，重置通过重建 iframe 释放旧运行环境。新增运行示例先登记到 <code>playground/example-registry.ts</code>（切换器与入口共用该清单），案例页位于 <code>playground/cases/</code>，复用 <code>playground/snippets/</code> 中的共享源码；案例 id 必须同步登记到 <code>playground/editor/editor-examples.ts</code> 的编辑模式示例（可运行代码与文档页「在 Playground 中编辑」、案例页「查看代码」均按同 id 解析）；<code>examples/snippets/</code> 中被 <code>&lt;&lt;&lt;</code> 引用的教学源码保持自包含样式，通过 <code>playground/cases/</code> 下的案例页包装接入演练场。</p><p>通过 <code>PlaygroundEmbed</code> 嵌入的业务打印示例在 <code>playground/editor/business-case-examples.ts</code> 注册，通过 <code>?raw</code> 载入 <code>examples/snippets/</code> 中的模板代码和 <code>main.js</code> 入口；<code>initialFile</code> 指定首次打开时显示的文件。入口代码渲染 HTML，并可通过 <code>window.__pgOutput</code> 提供 <code>print()</code> 和 <code>pdf()</code> 操作（<code>pdf()</code> 返回 PDF Blob），预览区只显示已提供的操作。Playground 默认使用「分栏」；文档内嵌时默认收起控制台，为预览留出空间。</p><p>执行 <code>pnpm docs:test</code> 验证已构建文档站，首次安装浏览器执行 <code>pnpm exec playwright install chromium</code>。测试覆盖及人工边界见<a href="./browser-acceptance.html">浏览器验收</a>。</p><p>教学截图来自实际浏览器，执行 <code>node tests/docs/capture-screenshots.mjs</code> 从端口 4174 的文档预览刷新截图，再重新构建文档。可传入完整的示例地址作为第一个参数。截图需检查启动遮罩已经消失、字体与图片完成加载，不能用占位图代替运行结果。</p><h2 id="内容与验证边界" tabindex="-1">内容与验证边界 <a class="header-anchor" href="#内容与验证边界" aria-label="Permalink to &quot;内容与验证边界&quot;">​</a></h2><p>主要入门教程使用 <code>&lt;&lt;&lt;</code> 引用示例源码，避免文案代码和实际文件分离。Markdown 内联片段不会由当前示例类型检查自动覆盖；类型通过与静态站构建通过，也不代表浏览器预览和打印已经验收。</p><p>当前站点发布手写指南与 API 参考，不生成完整源码 API 网站。多个指南页共用同一 runner 时，运行案例先在 <code>playground/runner.ts</code> 声明类型，再通过 <code>playground/cases/case-runner.vue</code> 组织运行按钮与输出面板。</p>`,22)])])}const m=d(a,[["render",t]]);export{u as __pageData,m as default};
